// ============================================================================
// src/lib/tools/multicast-mac-mapper/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the multicast group <-> MAC mapper.
//
// Every expected field below was derived on 2026-11-02 by a separate Python
// oracle (Python 3.13's ipaddress module for parsing and canonical text, plain
// integer arithmetic for the mappings, and its own reading of the two IANA
// registries; in the build's work folder), not by running this engine, and is
// compared here exactly. The set covers:
//   - both directions and both IP versions, and all three MAC notations;
//   - every IPv4 block of IANA's registry at its boundaries, every RFC 2365
//     scope, relative addresses, GLOP (RFC 3180's AS 5662, RFC 6676's AS
//     64496), UBM (RFC 6676's 234.192.0.2) and MCAST-TEST-NET;
//   - the 32:1 collision: 224.1.1.1, 239.1.1.1 and 239.129.1.1 on
//     01-00-5E-01-01-01, RFC 4541's 224.1.2.3 and 239.129.2.3, the article's
//     224.0.0.1 and 239.128.0.1, and the 32 groups pinned for several MACs;
//   - IPv6 flags, every kind of scope, SSM ranges (RFC 4607), unicast-prefix
//     and embedded-RP addresses (RFC 6676's examples), solicited-node (RFC
//     4291's example), RFC 3307's two mapping examples and IANA's names;
//   - 42 refusals: unicast addresses, class E, malformed text in every
//     notation, the upper half of 01-00-5E with IANA's row for each, the
//     broadcast address and group MACs outside both mappings.
// The page's Example (D-83) is the Learn article's worked group, 233.252.0.1.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
// The vector lines between the markers are generated by the oracle's script.
// ============================================================================

import { run, type MapperResult } from "./compute"; // the engine's public entry
import { EXAMPLE_INPUT, SAMPLE_INPUTS } from "./examples"; // the page's Example and sample chips, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "multicast-mac-mapper-golden-2026-11-02"; // the first set

/** One vector: an input, and either the fields expected or the error expected. */
export interface MapperVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from. */
  note: string;
  /** The text typed. */
  input: string;
  /** The fields expected, compared as subsets (objects by their listed keys, arrays element by element). */
  expect?: Record<string, unknown>;
  /** IPv4 forward: the 32 groups that share the MAC, in order. */
  sharingGroups?: string[];
  /** IPv4 reverse: every candidate IANA names, as [group, name], in order. */
  named?: [string, string][];
  /** Text every listed warning or note must contain, by list. */
  contains?: { warnings?: string[]; notes?: string[] };
  /** No warning expected. */
  noWarnings?: boolean;
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

/** The page's Example (D-83), re-exported for the conventional name. */
export { EXAMPLE_INPUT }; // 233.252.0.1

