/**
 * Whether `actual` holds `expected`: objects by the expected keys (recursively), arrays by length and element,
 * everything else exactly as JSON.
 * @param actual the reading's value
 * @param expected the vector's value
 * @returns true when it matches
 */
function matches(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) { // element by element
    if (!Array.isArray(actual) || actual.length !== expected.length) return false; // the lengths first
    return expected.every((e, i) => matches(actual[i], e)); // each element
  } // array
  if (expected !== null && typeof expected === "object") { // a subset object
    if (actual === null || typeof actual !== "object") return false; // nothing to compare with
    return Object.entries(expected as Record<string, unknown>).every(([k, v]) => matches((actual as Record<string, unknown>)[k], v)); // each field
  } // object
  return JSON.stringify(actual) === JSON.stringify(expected); // exact, as JSON
} // matches

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/**
 * Run every vector, and check that the Example is one of them.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  if (!MAPPER_VECTORS.some((v) => v.input === EXAMPLE_INPUT && v.expect)) failures.push("example: the page's Example is not a computed vector"); // D-83
  for (const s of SAMPLE_INPUTS) if (!MAPPER_VECTORS.some((v) => v.input === s && v.expect)) failures.push(`sample: "${s}" is not a computed vector`); // the chips too
  for (const v of MAPPER_VECTORS) { // each vector
    let r: MapperResult | null = null; // the reading
    try {
      r = run(v.input); // the engine
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e); // the refusal
      if (!v.expectError) failures.push(`${v.id}: unexpected error: ${msg}`); // should have computed
      else if (!v.expectError.test(msg)) failures.push(`${v.id}: error mismatch: ${msg}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.expectError) { failures.push(`${v.id}: expected an error, got a reading`); continue; } // should have refused
    if (v.expect) for (const [k, want] of Object.entries(v.expect)) if (!matches((r as unknown as Record<string, unknown>)[k], want)) failures.push(`${v.id}: ${k} differs: ${JSON.stringify((r as unknown as Record<string, unknown>)[k]).slice(0, 300)}`); // field by field
    if (v.sharingGroups) { // the 32 groups
      const got = r.direction === "forward" && r.family === "ipv4" ? r.sharing.map((g) => g.group) : []; // as listed
      if (JSON.stringify(got) !== JSON.stringify(v.sharingGroups)) failures.push(`${v.id}: sharing groups differ`); // order matters
    } // sharing
    if (v.named) { // the named candidates
      const got = r.direction === "reverse" && r.family === "ipv4" ? r.candidates.filter((c) => c.registered).map((c) => [c.group, c.registered]) : []; // as listed
      if (JSON.stringify(got) !== JSON.stringify(v.named)) failures.push(`${v.id}: named candidates differ: ${JSON.stringify(got).slice(0, 300)}`); // order matters
    } // named
    const c = v.contains ?? {}; // the texts expected
    for (const s of c.warnings ?? []) if (!r.warnings.some((w) => w.includes(s))) failures.push(`${v.id}: no warning contains "${s}"`); // warnings
    for (const s of c.notes ?? []) if (!r.notes.some((n) => n.includes(s))) failures.push(`${v.id}: no note contains "${s}"`); // notes
    if (v.noWarnings && r.warnings.length > 0) failures.push(`${v.id}: unexpected warnings: ${r.warnings.join(" | ").slice(0, 200)}`); // none expected
  } // vectors
  return { setId: GOLDEN_VECTOR_SET_ID, total: MAPPER_VECTORS.length, passed: MAPPER_VECTORS.length - new Set(failures.map((f) => f.split(":")[0])).size, failures }; // the report
} // verifyVectors
